  if(res.spectrumOnly){$('#aKpi').innerHTML=`<div class="stat"><span>Archivo</span><b style="font-size:14px">${esc(A.name)}</b></div><div class="stat"><span>Tipo</span><b style="font-size:14px">Espectro (f vs amplitud)</b></div><div class="stat"><span>Resolución</span><b>${fF(res.S.df,3)} Hz</b></div>`;
    $('#cWbox').hidden=true;$('#cEbox').hidden=true;const f=res.S.f,a=res.S.a,fm=num($('#aFmR').value)||f[f.length-1];const pts=[];for(let i=0;i<f.length;i++)if(f[i]<=fm)pts.push([f[i],lin?a[i]:dBof(a[i],res.scale)]);
    CH.S.setData({xType:'lin',xFmt:v=>f1(v,0)+' Hz',yFmt:v=>f1(v,lin?4:1),y2Fmt:v=>f1(v,1),yLabel:lin?'amplitud':'dB',hInclude:false,series:[{name:'Espectro',color:cssv('--dorado'),width:1.4,pts}],vlines:vl},true);
    $('#aFam').innerHTML='<div class="infobox">Archivo de espectro: se muestran los picos y los marcadores. Para clasificar por fase y envolvente se requiere la forma de onda en el tiempo.</div>';
    $('#aPeaks').innerHTML='<tr><th>Frecuencia (Hz)</th><th class="n">Amplitud</th><th class="n">SNR (dB)</th></tr>'+res.peaks.map(q=>`<tr><td>${fF(q.f,2)}</td><td class="n">${q.a.toPrecision(3)}</td><td class="n">${fF(q.snr,1)}</td></tr>`).join('');$('#aPhase').innerHTML='';$('#aSave').disabled=true;return}
  $('#aSave').disabled=false;$('#cWbox').hidden=false;$('#cEbox').hidden=false;
  const st=res.st,dl_=res.delta,rod=p.kind==='rod',lvl=rod&&dl_!=null?nivelRod(dl_):null;
  $('#aKpi').innerHTML=[['Nivel RMS',res.dBuV!=null?fF(res.dBuV,1)+' dBµV':fF(st.rms,4)+' '+unitTxt],['Pico',res.dPeak!=null?fF(res.dPeak,1)+' dBµV':fF(st.peak,4)+' '+unitTxt],...(rod?[['Δ vs línea base',dl_!=null?(dl_>=0?'+':'')+fF(dl_,1)+' dB · '+NIVEL[lvl]:'—',lvl>=2?'crit':lvl===1?'warn':'']]:[]),['Factor de cresta',fF(st.cf,2),st.cf>=CFG.cf[1]?'crit':st.cf>=CFG.cf[0]?'warn':''],['Curtosis',fF(st.kurt,2),st.kurt>=CFG.kurt[1]?'crit':st.kurt>=CFG.kurt[0]?'warn':''],['Asimetría',fF(st.skew,2)],['Muestras',res.n.toLocaleString('es-MX')],['Duración / fs',fF(res.dur,3)+' s · '+fF(res.fs,0)+' Hz'],['Línea (de la envolvente)',fF(res.fline,2)+' Hz']].map(([l,v,c])=>`<div class="stat ${c?'s-'+c:''}"><span>${l}</span><b style="font-size:16px">${v}</b></div>`).join('');
  const w0=num($('#aW0').value)||0,wl=num($('#aWl').value)||100,fs=res.fs,i0=Math.max(0,Math.floor(w0*fs/1000)),i1=Math.min(res.n,i0+Math.max(8,Math.floor(wl*fs/1000)));
